import boto3

def query_documents(table_name, partition_key, partition_value, sort_key=None, sort_value=None):
    dynamodb = boto3.resource('dynamodb')
    table = dynamodb.Table(table_name)

    if sort_key:
        response = table.query(
            KeyConditionExpression=(
                boto3.dynamodb.conditions.Key(partition_key).eq(partition_value) &
                boto3.dynamodb.conditions.Key(sort_key).eq(sort_value)
            )
        )
    else:
        response = table.scan(
            FilterExpression=boto3.dynamodb.conditions.Key(partition_key).eq(partition_value)
        )

    return response['Items']
